import Foundation
import SwiftData
import WCIWKit

/// Central coordinator for the user's watchlist: add/remove, refresh from TMDB, and
/// episode-watched bookkeeping.
///
/// All `ModelContext` mutations performed by this class run on the main actor — callers
/// are expected to pass the SwiftUI environment's context. The "last refresh" timestamp is
/// persisted in `UserDefaults` under `watchlistLastRefresh`.
@MainActor
final class WatchlistManager: ObservableObject {
    static let shared = WatchlistManager()

    private static let lastRefreshKey = "watchlistLastRefresh"

    private let tmdbService: TMDBService?

    private let defaults: UserDefaults

    let refreshPolicy: WatchlistRefreshPolicy

    @Published private(set) var isRefreshing = false

    var lastRefreshDate: Date? {
        get { defaults.object(forKey: Self.lastRefreshKey) as? Date }
        set { defaults.set(newValue, forKey: Self.lastRefreshKey) }
    }

    /// - Parameters:
    ///   - tmdbService: TMDB client. Defaults to a service constructed from `Info.plist`.
    ///     Passing `nil` and having no configured API key disables network refresh — the manager
    ///     still works for local watchlist mutations.
    ///   - defaults: Backing store for the last-refresh timestamp. Defaults to `.standard`.
    ///   - refreshPolicy: Staleness policy. Defaults to 24-hour refresh.
    init(
        tmdbService: TMDBService? = nil,
        defaults: UserDefaults = .standard,
        refreshPolicy: WatchlistRefreshPolicy = WatchlistRefreshPolicy()
    ) {
        self.tmdbService = tmdbService ?? (try? TMDBService())
        self.defaults = defaults
        self.refreshPolicy = refreshPolicy
    }

    // MARK: - Add/Remove Operations

    /// Adds an item to the watchlist if not already present.
    ///
    /// - Parameters:
    ///   - media: The media to add.
    ///   - context: SwiftData context. Inserts are made here; saving is up to SwiftData autosave.
    ///   - posterData: Optional pre-fetched poster bytes for offline display.
    /// - Returns: The newly created `WatchlistItem`, or `nil` if the item was already in the watchlist.
    /// - Note: For TV shows, fetches airing info from TMDB before insertion; a network failure is
    ///   non-fatal and the item is inserted with no next-episode metadata. Also triggers
    ///   `NotificationManager.requestPermissionIfNeeded()` as a side effect.
    @discardableResult
    func addToWatchlist(_ media: Media, context: ModelContext, posterData: Data? = nil) async -> WatchlistItem? {
        // Check if already in watchlist
        if isInWatchlist(mediaId: media.id, context: context) {
            return nil
        }

        // For TV shows, fetch airing info
        var airingInfo: TVShowAiringInfo?
        if media.mediaType == .tv, let service = tmdbService {
            do {
                airingInfo = try await service.getTVShowAiringInfo(tvId: media.id)
            } catch {
                // Continue with nil airing info if fetch fails
            }
        }

        // Create and insert the item
        let item = WatchlistItem(from: media, airingInfo: airingInfo, posterData: posterData)
        context.insert(item)

        // Request notification permission if not yet determined
        await NotificationManager.shared.requestPermissionIfNeeded()

        return item
    }

    /// Removes the item with the given media ID and cascade-deletes its `WatchedEpisode` records.
    ///
    /// - Returns: `true` if an item was removed; `false` if no matching item existed.
    @discardableResult
    func removeFromWatchlist(mediaId: Int, context: ModelContext) -> Bool {
        guard let item = fetchWatchlistItem(mediaId: mediaId, context: context) else {
            return false
        }
        context.delete(item)

        // Cascade: delete all watched episode records for this show
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.mediaId == mediaId }
        )
        if let episodes = try? context.fetch(descriptor) {
            for episode in episodes {
                context.delete(episode)
            }
        }

        return true
    }

    /// Whether a watchlist item exists for the given media ID.
    func isInWatchlist(mediaId: Int, context: ModelContext) -> Bool {
        fetchWatchlistItem(mediaId: mediaId, context: context) != nil
    }

    /// Looks up a watchlist item by media ID. Returns `nil` if not found or the fetch fails.
    func fetchWatchlistItem(mediaId: Int, context: ModelContext) -> WatchlistItem? {
        let descriptor = FetchDescriptor<WatchlistItem>(
            predicate: #Predicate { $0.mediaId == mediaId }
        )
        return try? context.fetch(descriptor).first
    }

    /// All watchlist items sorted by `dateAdded` descending (newest first).
    /// Returns `[]` on fetch failure.
    func fetchAllWatchlistItems(context: ModelContext) -> [WatchlistItem] {
        let descriptor = FetchDescriptor<WatchlistItem>(
            sortBy: [SortDescriptor(\.dateAdded, order: .reverse)]
        )
        return (try? context.fetch(descriptor)) ?? []
    }

    // MARK: - Refresh Logic

    /// Whether the watchlist is past its refresh interval relative to `currentDate`.
    /// Delegates to `refreshPolicy`. `currentDate` is injectable for tests.
    func needsRefresh(currentDate: Date = Date()) -> Bool {
        refreshPolicy.needsRefresh(lastRefreshDate: lastRefreshDate, currentDate: currentDate)
    }

    /// Refreshes airing info if the policy says it's due, or unconditionally when `force` is true.
    ///
    /// - Parameters:
    ///   - context: SwiftData context used to read and update items.
    ///   - force: When `true`, bypasses the staleness check.
    ///   - currentDate: Reference "now" — used for both the staleness check and the new
    ///     `lastRefreshDate` written to `UserDefaults`. Defaults to `Date()`.
    /// - Note: Updates `lastRefreshDate` on completion (success or partial failure).
    func refreshIfNeeded(context: ModelContext, force: Bool = false, currentDate: Date = Date()) async {
        guard force || needsRefresh(currentDate: currentDate) else {
            return
        }

        await refreshAllAiringInfo(context: context)
        lastRefreshDate = currentDate
    }

    /// Refreshes TMDB airing info for every TV show on the watchlist (movies are skipped).
    ///
    /// Network failures per item are non-fatal — the item retains its existing data and the
    /// loop continues. Saves the context once at the end and reschedules pending episode
    /// notifications with the new data.
    ///
    /// - Note: Sets `isRefreshing` to `true` for the duration of the call.
    func refreshAllAiringInfo(context: ModelContext) async {
        guard let service = tmdbService else { return }

        isRefreshing = true
        defer { isRefreshing = false }

        let items = fetchAllWatchlistItems(context: context)

        for item in items {
            // Only refresh TV shows, not movies
            guard item.isTVShow else { continue }

            do {
                let airingInfo = try await service.getTVShowAiringInfo(tvId: item.mediaId)
                item.update(with: airingInfo)
            } catch {
                // Keep existing data if refresh fails
            }
        }

        // Explicitly save changes to persist updated airing info
        try? context.save()

        // Reschedule episode notifications with updated airing data
        await NotificationManager.shared.rescheduleEpisodeNotifications(items: items)
    }

    /// Refreshes airing info for a single TV item. No-ops for movies.
    /// Saves the context on success; on network failure the existing data is kept.
    func refreshAiringInfo(for item: WatchlistItem, context: ModelContext) async {
        // Only refresh TV shows, not movies
        guard item.isTVShow, let service = tmdbService else { return }

        do {
            let airingInfo = try await service.getTVShowAiringInfo(tvId: item.mediaId)
            item.update(with: airingInfo)
            try? context.save()
        } catch {
            // Keep existing data if refresh fails
        }
    }

    // MARK: - Episode Tracking

    /// Marks an episode as watched. No-ops if a record for this `episodeId` already exists.
    func markEpisodeWatched(
        mediaId: Int,
        episodeId: Int,
        seasonNumber: Int,
        episodeNumber: Int,
        context: ModelContext
    ) {
        guard !isEpisodeWatched(episodeId: episodeId, context: context) else { return }

        let record = WatchedEpisode(
            episodeId: episodeId,
            mediaId: mediaId,
            seasonNumber: seasonNumber,
            episodeNumber: episodeNumber
        )
        context.insert(record)
    }

    /// Removes the watched record for `episodeId`. No-ops if no such record exists.
    func markEpisodeUnwatched(episodeId: Int, context: ModelContext) {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.episodeId == episodeId }
        )
        guard let record = try? context.fetch(descriptor).first else { return }
        context.delete(record)
    }

    /// Toggles the watched state for an episode.
    /// - Returns: `true` if the episode is now marked watched, `false` if it was just unmarked.
    @discardableResult
    func toggleEpisodeWatched(
        mediaId: Int,
        episodeId: Int,
        seasonNumber: Int,
        episodeNumber: Int,
        context: ModelContext
    ) -> Bool {
        if isEpisodeWatched(episodeId: episodeId, context: context) {
            markEpisodeUnwatched(episodeId: episodeId, context: context)
            return false
        } else {
            markEpisodeWatched(
                mediaId: mediaId,
                episodeId: episodeId,
                seasonNumber: seasonNumber,
                episodeNumber: episodeNumber,
                context: context
            )
            return true
        }
    }

    /// Whether a watched record exists for the given episode ID.
    func isEpisodeWatched(episodeId: Int, context: ModelContext) -> Bool {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.episodeId == episodeId }
        )
        let count = (try? context.fetchCount(descriptor)) ?? 0
        return count > 0
    }

    /// All watched-episode records for a given show. Order is unspecified.
    func watchedEpisodes(for mediaId: Int, context: ModelContext) -> [WatchedEpisode] {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.mediaId == mediaId }
        )
        return (try? context.fetch(descriptor)) ?? []
    }

    /// Number of watched episode records for one season of one show.
    func watchedEpisodeCount(for mediaId: Int, seasonNumber: Int, context: ModelContext) -> Int {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.mediaId == mediaId && $0.seasonNumber == seasonNumber }
        )
        return (try? context.fetchCount(descriptor)) ?? 0
    }

    /// Marks every episode in `episodes` as watched. Duplicates are filtered by `markEpisodeWatched`.
    func markSeasonWatched(mediaId: Int, episodes: [Episode], context: ModelContext) {
        for episode in episodes {
            markEpisodeWatched(
                mediaId: mediaId,
                episodeId: episode.id,
                seasonNumber: episode.seasonNumber,
                episodeNumber: episode.episodeNumber,
                context: context
            )
        }
    }

    /// Deletes all watched-episode records for the given show and season.
    func markSeasonUnwatched(mediaId: Int, seasonNumber: Int, context: ModelContext) {
        let descriptor = FetchDescriptor<WatchedEpisode>(
            predicate: #Predicate { $0.mediaId == mediaId && $0.seasonNumber == seasonNumber }
        )
        guard let episodes = try? context.fetch(descriptor) else { return }
        for episode in episodes {
            context.delete(episode)
        }
    }

}

import Foundation
import SwiftData

/// SwiftData record marking a single TV episode as watched by the user.
///
/// `episodeId` is the TMDB episode ID and is the unique key. `mediaId` denormalizes the show
/// ID for fast per-show queries without joining through the season.
@Model
final class WatchedEpisode {
    @Attribute(.unique) var episodeId: Int

    var mediaId: Int

    var seasonNumber: Int

    var episodeNumber: Int

    var dateWatched: Date

    init(
        episodeId: Int,
        mediaId: Int,
        seasonNumber: Int,
        episodeNumber: Int,
        dateWatched: Date = Date()
    ) {
        self.episodeId = episodeId
        self.mediaId = mediaId
        self.seasonNumber = seasonNumber
        self.episodeNumber = episodeNumber
        self.dateWatched = dateWatched
    }
}

