import UserNotifications
import SwiftData
import WCIWKit

/// Coordinator for all local notifications: permission, scheduling, badge management,
/// and tap-handling routing.
///
/// Persists user prefs (`notificationsEnabled`) and last-foreground timestamp (`lastOpenedDate`)
/// in `UserDefaults`. Wraps `UNUserNotificationCenter` and turns `NotificationContent` payloads
/// into `UNNotificationRequest`s. Identifier conventions: `episode-<mediaId>`, `streaming-<mediaId>`.
@MainActor
final class NotificationManager: ObservableObject {
    static let shared = NotificationManager()

    @Published private(set) var isAuthorized = false

    @Published var pendingMediaId: Int?
    @Published var pendingMediaType: MediaType?

    private static let notificationsEnabledKey = "notificationsEnabled"

    private static let lastOpenedDateKey = "lastOpenedDate"

    var lastOpenedDate: Date {
        get {
            let interval = UserDefaults.standard.double(forKey: Self.lastOpenedDateKey)
            return interval > 0 ? Date(timeIntervalSince1970: interval) : .distantPast
        }
        set {
            UserDefaults.standard.set(newValue.timeIntervalSince1970, forKey: Self.lastOpenedDateKey)
        }
    }

    var notificationsEnabled: Bool {
        get { UserDefaults.standard.bool(forKey: Self.notificationsEnabledKey) }
        set { UserDefaults.standard.set(newValue, forKey: Self.notificationsEnabledKey) }
    }

    private init() {
        Task { await refreshAuthorizationStatus() }
    }

    // MARK: - Permission

    /// Prompts the user for notification permission.
    ///
    /// - Returns: `true` if granted, `false` if denied or if the request errored.
    /// - Note: On grant, sets `notificationsEnabled = true` (user preference). Updates `isAuthorized`.
    func requestPermission() async -> Bool {
        do {
            let granted = try await UNUserNotificationCenter.current()
                .requestAuthorization(options: [.alert, .badge, .sound])
            isAuthorized = granted
            if granted {
                notificationsEnabled = true
            }
            return granted
        } catch {
            return false
        }
    }

    /// Requests permission only if the user has not yet been asked.
    /// No-ops when status is `.authorized`, `.denied`, or `.provisional`.
    func requestPermissionIfNeeded() async {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        guard settings.authorizationStatus == .notDetermined else { return }
        _ = await requestPermission()
    }

    /// Re-reads system authorization status into `isAuthorized`. Call after app foreground
    /// so view state reflects changes made in Settings.app.
    func refreshAuthorizationStatus() async {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        isAuthorized = settings.authorizationStatus == .authorized
    }

    /// `true` only when the user has both system authorization and the in-app `notificationsEnabled`
    /// toggle on. Scheduling functions short-circuit on `false`.
    func shouldScheduleNotifications() -> Bool {
        isAuthorized && notificationsEnabled
    }

    // MARK: - Episode Notifications

    /// Cancels all pending episode notifications and re-schedules them from current watchlist data.
    ///
    /// - Parameter items: Current watchlist. Non-TV items and items without `nextEpisodeDate` are
    ///   skipped.
    /// - Note: Removes pending requests whose identifier starts with `"episode-"`. Schedules
    ///   replacement notifications in chronological order, with badge counts (1, 2, 3, ...)
    ///   assigned to episodes that fire after `lastOpenedDate`. Earlier episodes carry no badge.
    ///   Silently returns when scheduling is disabled.
    func rescheduleEpisodeNotifications(items: [WatchlistItem]) async {
        guard shouldScheduleNotifications() else { return }

        let center = UNUserNotificationCenter.current()

        // Remove all existing episode notifications
        let pendingRequests = await center.pendingNotificationRequests()
        let episodeIds = pendingRequests
            .filter { $0.identifier.hasPrefix("episode-") }
            .map(\.identifier)
        center.removePendingNotificationRequests(withIdentifiers: episodeIds)

        // Build content for all eligible episodes
        var contentItems: [(content: NotificationContent, airDate: Date)] = []
        for item in items where item.isTVShow {
            guard let airDate = item.nextEpisodeDate else { continue }

            guard let content = NotificationContentBuilder.episodeNotification(
                mediaId: item.mediaId,
                title: item.title,
                seasonNumber: item.nextSeasonNumber,
                episodeNumber: item.nextEpisodeNumber,
                episodeName: item.nextEpisodeName,
                airDate: airDate
            ) else { continue }

            contentItems.append((content, airDate))
        }

        // Schedule chronologically so badge values (1, 2, 3...) match air order
        let sortedItems = contentItems.sorted { $0.airDate < $1.airDate }
        var badgeOffset = 0
        for (content, airDate) in sortedItems {
            if airDate > lastOpenedDate {
                badgeOffset += 1
                await scheduleNotification(content, badgeCount: badgeOffset)
            } else {
                await scheduleNotification(content)
            }
        }
    }

    // MARK: - Movie Availability Notifications

    /// Schedules an immediate "now streaming" notification for a watchlisted movie.
    ///
    /// Badge value is set to the count of upcoming episode notifications plus 1, so the badge
    /// reflects total unseen items.
    /// - Note: Silently returns when scheduling is disabled.
    func notifyMovieAvailable(item: WatchlistItem, serviceName: String) async {
        guard shouldScheduleNotifications() else { return }

        let content = NotificationContentBuilder.movieAvailableNotification(
            mediaId: item.mediaId,
            title: item.title,
            serviceName: serviceName
        )

        // Count pending episode notifications that will fire after lastOpenedDate
        let center = UNUserNotificationCenter.current()
        let pendingRequests = await center.pendingNotificationRequests()
        let episodeCount = pendingRequests
            .filter { $0.identifier.hasPrefix("episode-") }
            .compactMap { $0.trigger as? UNCalendarNotificationTrigger }
            .compactMap { (trigger: UNCalendarNotificationTrigger) -> Date? in
                Calendar.current.date(from: trigger.dateComponents)
            }
            .filter { $0 > lastOpenedDate }
            .count

        await scheduleNotification(content, badgeCount: episodeCount + 1)
    }

    // MARK: - Scheduling

    private func scheduleNotification(_ content: NotificationContent, badgeCount: Int? = nil) async {
        let notificationContent = UNMutableNotificationContent()
        notificationContent.title = content.title
        notificationContent.body = content.body
        notificationContent.categoryIdentifier = content.categoryIdentifier
        notificationContent.threadIdentifier = content.threadIdentifier
        notificationContent.sound = .default
        notificationContent.userInfo = [
            "mediaId": content.mediaId,
            "mediaType": content.mediaType
        ]

        if let badgeCount {
            notificationContent.badge = NSNumber(value: badgeCount)
        }

        // Create trigger
        let trigger: UNNotificationTrigger?
        if let triggerDate = content.triggerDate {
            let components = Calendar.current.dateComponents(
                [.year, .month, .day, .hour, .minute],
                from: triggerDate
            )
            trigger = UNCalendarNotificationTrigger(dateMatching: components, repeats: false)
        } else {
            // Immediate delivery (for movie availability)
            trigger = nil
        }

        let request = UNNotificationRequest(
            identifier: content.identifier,
            content: notificationContent,
            trigger: trigger
        )

        do {
            try await UNUserNotificationCenter.current().add(request)
        } catch {
            // Notification scheduling failed — non-fatal
        }
    }

    // MARK: - Badge Management

    /// Records the current time as `lastOpenedDate` and clears the app icon badge.
    /// Call on app foreground / scene activation.
    /// - Note: Writes to `UserDefaults` and calls `setBadgeCount(0)`. Errors from the system
    ///   are swallowed.
    func clearBadge() async {
        lastOpenedDate = Date()
        try? await UNUserNotificationCenter.current().setBadgeCount(0)
    }

    // MARK: - Cancellation

    /// Cancels every pending notification request and clears the badge.
    func cancelAllNotifications() {
        UNUserNotificationCenter.current().removeAllPendingNotificationRequests()
        Task { await clearBadge() }
    }

    /// Cancels both the episode and streaming notifications associated with one media item.
    /// Targets identifiers `"episode-<mediaId>"` and `"streaming-<mediaId>"`.
    func cancelNotifications(for mediaId: Int) {
        let identifiers = ["episode-\(mediaId)", "streaming-\(mediaId)"]
        UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: identifiers)
    }

    // MARK: - Notification Response Handling

    /// Records a tapped notification so SwiftUI can navigate to the related media's detail.
    ///
    /// Stores the values in `pendingMediaId` / `pendingMediaType`. No-ops when either input is
    /// missing or when `mediaTypeRaw` is not a recognized `MediaType`.
    func handleNotificationTap(mediaId: Int?, mediaTypeRaw: String?) {
        guard let mediaId,
              let mediaTypeRaw,
              let mediaType = MediaType(rawValue: mediaTypeRaw) else { return }
        pendingMediaId = mediaId
        pendingMediaType = mediaType
    }

    // MARK: - Notification Categories

    // MARK: - Debug Helpers

    #if DEBUG
    func ensureDebugPermission() async -> String? {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        switch settings.authorizationStatus {
        case .authorized:
            return nil
        case .notDetermined:
            let granted = await requestPermission()
            return granted ? nil : "Permission denied"
        case .denied:
            return "Notifications denied in Settings"
        default:
            return "Notification permission unavailable"
        }
    }

    func scheduleTestEpisodeNotification() async -> String {
        if let error = await ensureDebugPermission() {
            return error
        }

        let content = UNMutableNotificationContent()
        content.title = "Breaking Bad"
        content.body = "Felina (S5 E16) airs today"
        content.categoryIdentifier = NotificationCategory.newEpisode.rawValue
        content.threadIdentifier = "episode-1396"
        content.sound = .default
        content.badge = NSNumber(value: 1)
        content.userInfo = ["mediaId": 1396, "mediaType": "tv"]

        let trigger = UNTimeIntervalNotificationTrigger(timeInterval: 5, repeats: false)
        let request = UNNotificationRequest(identifier: "debug-episode", content: content, trigger: trigger)
        do {
            try await UNUserNotificationCenter.current().add(request)
            return "Episode notification scheduled (5 sec)"
        } catch {
            return "Failed: \(error.localizedDescription)"
        }
    }

    func scheduleTestMovieNotification() async -> String {
        if let error = await ensureDebugPermission() {
            return error
        }

        let content = UNMutableNotificationContent()
        content.title = "Fight Club"
        content.body = "Now streaming on Netflix"
        content.categoryIdentifier = NotificationCategory.nowStreaming.rawValue
        content.threadIdentifier = "streaming-550"
        content.sound = .default
        content.badge = NSNumber(value: 1)
        content.userInfo = ["mediaId": 550, "mediaType": "movie"]

        let trigger = UNTimeIntervalNotificationTrigger(timeInterval: 5, repeats: false)
        let request = UNNotificationRequest(identifier: "debug-movie", content: content, trigger: trigger)
        do {
            try await UNUserNotificationCenter.current().add(request)
            return "Movie notification scheduled (5 sec)"
        } catch {
            return "Failed: \(error.localizedDescription)"
        }
    }
    #endif

    // MARK: - Notification Categories

    /// Registers the app's notification categories with the system. Call once on app launch
    /// from `AppDelegate.didFinishLaunchingWithOptions`.
    static func registerCategories() {
        let episodeCategory = UNNotificationCategory(
            identifier: NotificationCategory.newEpisode.rawValue,
            actions: [],
            intentIdentifiers: []
        )
        let streamingCategory = UNNotificationCategory(
            identifier: NotificationCategory.nowStreaming.rawValue,
            actions: [],
            intentIdentifiers: []
        )
        UNUserNotificationCenter.current().setNotificationCategories([
            episodeCategory,
            streamingCategory
        ])
    }
}

import Foundation

/// A single TV episode as returned by TMDB's season-details endpoint.
public struct Episode: Sendable {
    public let id: Int

    public let episodeNumber: Int

    public let seasonNumber: Int

    public let name: String

    public let overview: String

    public let airDate: String?

    public let stillPath: String?

    public let runtime: Int?

    public init(
        id: Int,
        episodeNumber: Int,
        seasonNumber: Int,
        name: String,
        overview: String,
        airDate: String? = nil,
        stillPath: String? = nil,
        runtime: Int? = nil
    ) {
        self.id = id
        self.episodeNumber = episodeNumber
        self.seasonNumber = seasonNumber
        self.name = name
        self.overview = overview
        self.airDate = airDate
        self.stillPath = stillPath
        self.runtime = runtime
    }
}

// MARK: - Computed Properties

extension Episode {
    /// Fully qualified TMDB still-frame URL at `w300` width, or `nil` if `stillPath` is missing.
    public var stillURL: URL? {
        guard let stillPath else { return nil }
        return URL(string: "https://image.tmdb.org/t/p/w300\(stillPath)")
    }

    /// Runtime rendered as `"N min"`, or `nil` when runtime is missing or non-positive.
    public var formattedRuntime: String? {
        guard let runtime, runtime > 0 else { return nil }
        return "\(runtime) min"
    }

    /// Whether the episode is on or before "today" in the device's local calendar.
    ///
    /// Returns `true` when `airDate` is missing or unparseable — episodes with no known air date
    /// are treated as already aired so they don't surface in "upcoming" UI by default.
    /// - Note: Compares against end-of-day local time, so an episode airing today returns `true`.
    public var hasAired: Bool {
        guard let airDate else { return true }
        let parser = DateFormatter()
        parser.dateFormat = "yyyy-MM-dd"
        parser.locale = Locale(identifier: "en_US_POSIX")
        guard let date = parser.date(from: airDate) else { return true }
        return date <= Calendar.current.startOfDay(for: Date()).addingTimeInterval(86400 - 1)
    }

    /// `airDate` rendered in the user's locale with `DateFormatter.Style.full`, or `nil` if
    /// the date is missing or unparseable.
    public var formattedAirDate: String? {
        guard let airDate else { return nil }
        let parser = DateFormatter()
        parser.dateFormat = "yyyy-MM-dd"
        parser.locale = Locale(identifier: "en_US_POSIX")
        guard let date = parser.date(from: airDate) else { return nil }
        let formatter = DateFormatter()
        formatter.dateStyle = .full
        formatter.timeStyle = .none
        return formatter.string(from: date)
    }
}

